if(typeof require==='function'){var Constants=require('./constants');var Upgrade=require('./upgrade');}var ShieldUpgrade=Upgrade.subclass();ShieldUpgrade.fields({_lifetime:0,_weakened:false});ShieldUpgrade.classMethods({createInitialUpgradeState:function(id,playerId,lifetime){var fields={_lifetime:lifetime,_weakened:false};return Upgrade.createInitialUpgradeState(id,playerId,Constants.UPGRADE_TYPES.SHIELD,JSON.stringify(fields));}});ShieldUpgrade.methods({update:function(deltaTime){this._lifetime-=deltaTime;if(!this._weakened){if(this._lifetime<=Constants.SHIELD_WEAKEN_TIME){this._weakened=true;this._emitEvent(Upgrade._EVENTS.UPGRADE_WEAKENED,this.id);}}},done:function(){return this._lifetime<=0;}});if(typeof module==='object'){module.exports=ShieldUpgrade;}